type User = { name:string role:string }
let <UserCard user:User /> =
  <div class="card">
    <h3>{user.name}</h3>
    <p>{user.role}</p>
  </div>
let team:User+ = { <User name="Ada" role="Engineer" /> <User name="Grace" role="Admiral" /> }
<ul>
  for user in team {
    <li><UserCard user={user} /></li>
  }
</ul>
